:root {
  --bg: #e8f4f8;
  --primary: #2196f3;
  --accent: #ff5722;
  --text: #1a237e;
  --radius: 10px;
  --font: system-ui, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  font-family: var(--font);
}

#game-canvas {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--bg);
}

const canvas = document.getElementById('game-canvas');
if (!canvas) throw new Error('No canvas');
const ctx = canvas.getContext('2d');

// --- Palette (matches style.css) ---
const C = {
  bg:      '#e8f4f8',
  primary: '#2196f3',
  accent:  '#ff5722',
  text:    '#1a237e',
  lane:    '#cce8f4',
  player:  '#2196f3',
  enemy:   '#ff5722',
  coin:    '#ffc107',
  trail:   'rgba(33,150,243,0.15)',
};

// --- State ---
let gameState = 'menu'; // 'menu' | 'playing' | 'gameover'
let score = 0;
let bestScore = parseInt(localStorage.getItem('hc_dodge_best') || '0', 10);
let lastTime = 0;
let frameCount = 0;

// --- Canvas resize ---
function resizeCanvas() {
  canvas.width  = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', () => { resizeCanvas(); layoutGame(); });
resizeCanvas();

// --- Layout helpers ---
let W, H, CX, CY;
let laneCount = 4;
let laneWidth, laneStartX;
let playerY, playerR;
let enemyR;

function layoutGame() {
  W  = canvas.width;
  H  = canvas.height;
  CX = W / 2;
  CY = H / 2;
  laneWidth  = Math.min(W * 0.8 / laneCount, 90);
  laneStartX = CX - (laneCount * laneWidth) / 2;
  playerY    = H * 0.78;
  playerR    = laneWidth * 0.28;
  enemyR     = laneWidth * 0.27;
}
layoutGame();

// --- Player ---
let player = { lane: 1, x: 0, y: 0, r: 0, targetX: 0, squish: 1, trail: [] };

function resetPlayer() {
  player.lane    = Math.floor(laneCount / 2) - 1;
  player.x       = laneCenter(player.lane);
  player.targetX = player.x;
  player.y       = playerY;
  player.r       = playerR;
  player.squish  = 1;
  player.trail   = [];
}

function laneCenter(l) {
  return laneStartX + l * laneWidth + laneWidth / 2;
}

// --- Enemies ---
let enemies = [];
let spawnTimer = 0;
let spawnInterval = 1.4;
let speedBase = 280;

function spawnEnemy() {
  // Pick a random subset of lanes (1-3 blocked)
  let blocked = Math.floor(Math.random() * 3) + 1;
  let lanes = [];
  for (let i = 0; i < laneCount; i++) lanes.push(i);
  // Shuffle
  for (let i = lanes.length - 1; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    [lanes[i], lanes[j]] = [lanes[j], lanes[i]];
  }
  let activeLanes = lanes.slice(0, blocked);
  for (let l of activeLanes) {
    enemies.push({
      lane: l,
      x: laneCenter(l),
      y: -enemyR * 2,
      r: enemyR,
      speed: speedBase,
      rot: 0,
    });
  }
}

// --- Coins ---
let coins = [];
let coinTimer = 0;
let coinInterval = 2.2;

function spawnCoin() {
  let l = Math.floor(Math.random() * laneCount);
  coins.push({ lane: l, x: laneCenter(l), y: -20, r: playerR * 0.4, speed: speedBase * 0.7, collected: false });
}

// --- Particles ---
let particles = [];

function burst(x, y, color, n) {
  for (let i = 0; i < n; i++) {
    let angle = Math.random() * Math.PI * 2;
    let speed = 80 + Math.random() * 160;
    particles.push({ x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, r: 4 + Math.random() * 6, life: 1, color });
  }
}

// --- Input ---
let touchStartX = null;
let targetLane  = -1;

canvas.addEventListener('pointerdown', e => {
  let r = canvas.getBoundingClientRect();
  let tx = e.clientX - r.left;
  const ty  = e.clientY - r.top;

  if (gameState === 'menu') {
    startGame();
    return;
  }
  if (gameState === 'gameover') {
    restartGame();
    return;
  }
  if (gameState === 'playing') {
    touchStartX = tx;
    // Tap left or right of player
    if (tx < CX) {
      moveLane(-1);
    } else {
      moveLane(1);
    }
  }
});

canvas.addEventListener('pointermove', e => {
  if (gameState !== 'playing' || touchStartX === null) return;
  let r = canvas.getBoundingClientRect();
  let tx = e.clientX - r.left;
  let dx = tx - touchStartX;
  if (Math.abs(dx) > laneWidth * 0.35) {
    moveLane(dx > 0 ? 1 : -1);
    touchStartX = tx;
  }
});

canvas.addEventListener('pointerup', () => { touchStartX = null; });
canvas.addEventListener('pointercancel', () => { touchStartX = null; });

// Keyboard support
window.addEventListener('keydown', e => {
  if (gameState === 'menu')     { startGame(); return; }
  if (gameState === 'gameover') { restartGame(); return; }
  if (e.key === 'ArrowLeft')  moveLane(-1);
  if (e.key === 'ArrowRight') moveLane(1);
});

function moveLane(dir) {
  let next = player.lane + dir;
  if (next < 0 || next >= laneCount) return;
  player.lane    = next;
  player.targetX = laneCenter(next);
  player.squish  = 1.25;
}

// --- Game functions ---
function startGame() {
  gameState     = 'playing';
  score         = 0;
  enemies       = [];
  coins         = [];
  particles     = [];
  spawnTimer    = 0;
  coinTimer     = 0;
  spawnInterval = 1.4;
  speedBase     = 280;
  frameCount    = 0;
  resetPlayer();
}

function restartGame() {
  startGame();
}

function endGame() {
  gameState = 'gameover';
  burst(player.x, player.y, C.accent, 18);
  try {
    if (score > bestScore) {
      bestScore = score;
      localStorage.setItem('hc_dodge_best', bestScore);
    }
  } catch(_) {}
}

// --- Update ---
function update(dt) {
  frameCount++;
  // Difficulty ramp
  if (frameCount % 360 === 0) {
    spawnInterval = Math.max(0.55, spawnInterval - 0.08);
    speedBase     = Math.min(620, speedBase + 22);
  }

  // Player lerp
  player.x      += (player.targetX - player.x) * Math.min(1, dt * 14);
  player.squish += (1 - player.squish) * Math.min(1, dt * 10);
  player.r       = playerR;

  // Trail
  player.trail.push({ x: player.x, y: player.y });
  if (player.trail.length > 8) player.trail.shift();

  // Spawn enemies
  spawnTimer += dt;
  if (spawnTimer >= spawnInterval) {
    spawnTimer = 0;
    spawnEnemy();
  }

  // Spawn coins
  coinTimer += dt;
  if (coinTimer >= coinInterval) {
    coinTimer = 0;
    spawnCoin();
  }

  // Move enemies
  for (let i = enemies.length - 1; i >= 0; i--) {
    let en = enemies[i];
    en.y  += en.speed * dt;
    en.rot += dt * 2;
    // recenter in case of resize
    en.x = laneCenter(en.lane);
    if (en.y > H + en.r * 2) {
      enemies.splice(i, 1);
      score++;
      continue;
    }
    // Collision
    let dx = player.x - en.x;
    let dy = player.y - en.y;
    let dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < player.r * 0.8 + en.r * 0.8) {
      endGame();
      return;
    }
  }

  // Move coins
  for (let i = coins.length - 1; i >= 0; i--) {
    let c = coins[i];
    c.y += c.speed * dt;
    c.x  = laneCenter(c.lane);
    if (c.y > H + 20) { coins.splice(i, 1); continue; }
    if (!c.collected) {
      let dx = player.x - c.x;
      let dy = player.y - c.y;
      if (Math.sqrt(dx * dx + dy * dy) < player.r + c.r) {
        c.collected = true;
        score += 3;
        burst(c.x, c.y, C.coin, 8);
        coins.splice(i, 1);
      }
    }
  }

  // Particles
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.x   += p.vx * dt;
    p.y   += p.vy * dt;
    p.vy  += 200 * dt;
    p.life -= dt * 1.8;
    p.r   *= 0.98;
    if (p.life <= 0) particles.splice(i, 1);
  }
}

// --- Draw helpers ---
function drawRoundRect(x, y, w, h, r, fill, stroke) {
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, r);
  if (fill)   { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 2; ctx.stroke(); }
}

function drawLanes() {
  for (let i = 0; i < laneCount; i++) {
    let x = laneStartX + i * laneWidth;
    ctx.fillStyle = i % 2 === 0 ? C.lane : C.bg;
    ctx.fillRect(x, 0, laneWidth, H);
    // lane separator
    ctx.strokeStyle = 'rgba(33,150,243,0.12)';
    ctx.lineWidth   = 1;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H);
    ctx.stroke();
  }
  // right edge
  let ex = laneStartX + laneCount * laneWidth;
  ctx.strokeStyle = 'rgba(33,150,243,0.12)';
  ctx.lineWidth   = 1;
  ctx.beginPath();
  ctx.moveTo(ex, 0);
  ctx.lineTo(ex, H);
  ctx.stroke();
}

function drawPlayer() {
  // Trail
  for (let i = 0; i < player.trail.length; i++) {
    let t    = i / player.trail.length;
    let tr   = player.trail[i];
    let size = playerR * t * 0.7;
    ctx.beginPath();
    ctx.arc(tr.x, tr.y, size, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(33,150,243,${t * 0.18})`;
    ctx.fill();
  }

  // Body (squish effect)
  let sx = 1 / player.squish;
  let sy = player.squish;
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.scale(sx, sy);
  // Shadow
  ctx.beginPath();
  ctx.ellipse(0, playerR * 0.2, playerR * 0.7 * player.squish, playerR * 0.2, 0, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(33,150,243,0.15)';
  ctx.fill();
  // Main circle
  ctx.beginPath();
  ctx.arc(0, 0, playerR, 0, Math.PI * 2);
  ctx.fillStyle = C.player;
  ctx.fill();
  // Shine
  ctx.beginPath();
  ctx.arc(-playerR * 0.28, -playerR * 0.28, playerR * 0.3, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.fill();
  // Eyes
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-playerR * 0.27, -playerR * 0.1, playerR * 0.17, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc( playerR * 0.27, -playerR * 0.1, playerR * 0.17, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.text;
  ctx.beginPath(); ctx.arc(-playerR * 0.27, -playerR * 0.1, playerR * 0.08, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc( playerR * 0.27, -playerR * 0.1, playerR * 0.08, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

function drawEnemy(en) {
  ctx.save();
  ctx.translate(en.x, en.y);
  ctx.rotate(en.rot);
  // Body
  ctx.beginPath();
  for (let i = 0; i < 4; i++) {
    let a = (i / 4) * Math.PI * 2 - Math.PI / 4;
    let r = en.r;
    if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
    else         ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  ctx.closePath();
  ctx.fillStyle = C.enemy;
  ctx.fill();
  // Inner square
  ctx.beginPath();
  for (let i = 0; i < 4; i++) {
    let a = (i / 4) * Math.PI * 2 - Math.PI / 4;
    let r = en.r * 0.5;
    if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
    else         ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  ctx.closePath();
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.fill();
  ctx.restore();
}

function drawCoin(c) {
  ctx.save();
  ctx.translate(c.x, c.y);
  // Outer ring
  ctx.beginPath();
  ctx.arc(0, 0, c.r, 0, Math.PI * 2);
  ctx.fillStyle   = C.coin;
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.5)';
  ctx.lineWidth   = 2;
  ctx.stroke();
  // Inner
  ctx.beginPath();
  ctx.arc(0, 0, c.r * 0.55, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,255,255,0.35)';
  ctx.fill();
  ctx.restore();
}

function drawParticles() {
  for (let p of particles) {
    ctx.save();
    ctx.globalAlpha = Math.max(0, p.life);
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fillStyle = p.color;
    ctx.fill();
    ctx.restore();
  }
}

function drawHUD() {
  // Score box
  let fontSize = Math.min(W * 0.09, 44);
  ctx.font      = `bold ${fontSize}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  // Score
  ctx.fillStyle = C.text;
  ctx.fillText(score, CX, H * 0.08 + fontSize * 0.4);
  // Best
  let smFont = Math.min(W * 0.04, 18);
  ctx.font      = `${smFont}px system-ui, sans-serif`;
  ctx.fillStyle = 'rgba(33,35,126,0.45)';
  ctx.fillText(`BEST ${bestScore}`, CX, H * 0.08 + fontSize + smFont);

  // Swipe hint (first few seconds)
  if (frameCount < 150) {
    ctx.globalAlpha = 1 - frameCount / 150;
    ctx.font        = `${smFont * 1.1}px system-ui, sans-serif`;
    ctx.fillStyle   = C.primary;
    ctx.fillText('TAP LEFT / RIGHT TO MOVE', CX, H * 0.92);
    ctx.globalAlpha = 1;
  }
}

// --- Draw main ---
function draw() {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, W, H);

  drawLanes();

  // Coins
  for (let c of coins) drawCoin(c);

  // Enemies
  for (let en of enemies) drawEnemy(en);

  // Player
  drawPlayer();

  // Particles
  drawParticles();

  // HUD
  drawHUD();
}

// --- Menu ---
function drawMenu() {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, W, H);
  drawLanes();

  // Title card
  let cardW = Math.min(W * 0.8, 340);
  let cardH = H * 0.45;
  let cardX = CX - cardW / 2;
  let cardY = CY - cardH / 2 - H * 0.04;
  drawRoundRect(cardX, cardY, cardW, cardH, 18, 'rgba(255,255,255,0.85)');

  // Title
  let tFont = Math.min(W * 0.1, 46);
  ctx.font      = `bold ${tFont}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.fillStyle = C.primary;
  ctx.fillText('DODGE!', CX, cardY + cardH * 0.32);

  // Subtitle
  let sFont = Math.min(W * 0.045, 20);
  ctx.font      = `${sFont}px system-ui, sans-serif`;
  ctx.fillStyle = C.text;
  ctx.fillText('Dodge the spinning squares', CX, cardY + cardH * 0.50);
  ctx.fillText('Collect gold coins for bonus', CX, cardY + cardH * 0.63);

  // Best score
  let bFont = Math.min(W * 0.04, 16);
  ctx.font      = `bold ${bFont}px system-ui, sans-serif`;
  ctx.fillStyle = C.accent;
  ctx.fillText(`BEST: ${bestScore}`, CX, cardY + cardH * 0.80);

  // Play button
  let btnW = Math.min(W * 0.55, 220);
  let btnH = Math.min(H * 0.075, 56);
  let btnX = CX - btnW / 2;
  let btnY = cardY + cardH + H * 0.04;
  drawRoundRect(btnX, btnY, btnW, btnH, 28, C.primary);
  ctx.font      = `bold ${Math.min(W * 0.055, 24)}px system-ui, sans-serif`;
  ctx.fillStyle = '#fff';
  ctx.textAlign = 'center';
  ctx.fillText('PLAY', CX, btnY + btnH * 0.64);

  // Animated demo enemy
  let t   = Date.now() / 1000;
  let dex = CX + Math.sin(t * 1.5) * laneWidth;
  let dey = CY + H * 0.28;
  ctx.save();
  ctx.translate(dex, dey);
  ctx.rotate(t * 2);
  ctx.beginPath();
  for (let i = 0; i < 4; i++) {
    let a = (i / 4) * Math.PI * 2 - Math.PI / 4;
    let r = enemyR;
    if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
    else         ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  ctx.closePath();
  ctx.fillStyle = C.enemy;
  ctx.fill();
  ctx.restore();
}

// --- Gameover ---
function drawGameover() {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, W, H);
  drawLanes();
  drawParticles();

  // Overlay
  ctx.fillStyle = 'rgba(232,244,248,0.72)';
  ctx.fillRect(0, 0, W, H);

  let cardW = Math.min(W * 0.82, 340);
  let cardH = H * 0.44;
  let cardX = CX - cardW / 2;
  let cardY = CY - cardH / 2;
  drawRoundRect(cardX, cardY, cardW, cardH, 18, '#fff');

  // Game Over title
  let tFont = Math.min(W * 0.09, 40);
  ctx.font      = `bold ${tFont}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.fillStyle = C.accent;
  ctx.fillText('GAME OVER', CX, cardY + cardH * 0.27);

  // Score
  let sFont = Math.min(W * 0.065, 30);
  ctx.font      = `bold ${sFont}px system-ui, sans-serif`;
  ctx.fillStyle = C.text;
  ctx.fillText(`Score: ${score}`, CX, cardY + cardH * 0.50);

  // Best
  let bFont = Math.min(W * 0.045, 20);
  ctx.font      = `${bFont}px system-ui, sans-serif`;
  ctx.fillStyle = score >= bestScore ? C.primary : 'rgba(33,35,126,0.5)';
  ctx.fillText(score >= bestScore ? '🏆 New Best!' : `Best: ${bestScore}`, CX, cardY + cardH * 0.70);

  // Retry button
  let btnW = Math.min(W * 0.55, 220);
  let btnH = Math.min(H * 0.075, 56);
  let btnX = CX - btnW / 2;
  let btnY = cardY + cardH + H * 0.035;
  drawRoundRect(btnX, btnY, btnW, btnH, 28, C.primary);
  ctx.font      = `bold ${Math.min(W * 0.055, 24)}px system-ui, sans-serif`;
  ctx.fillStyle = '#fff';
  ctx.fillText('PLAY AGAIN', CX, btnY + btnH * 0.64);
}

// --- Game Loop ---
function gameLoop(ts) {
  const dt = Math.min((ts - lastTime) / 1000, 0.05);
  lastTime  = ts;

  if (gameState === 'playing') {
    update(dt);
    draw();
  } else if (gameState === 'menu') {
    layoutGame();
    drawMenu();
  } else if (gameState === 'gameover') {
    // Still update particles
    for (let i = particles.length - 1; i >= 0; i--) {
      let p = particles[i];
      p.x   += p.vx * dt;
      p.y   += p.vy * dt;
      p.vy  += 200 * dt;
      p.life -= dt * 1.8;
      if (p.life <= 0) particles.splice(i, 1);
    }
    drawGameover();
  }

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
